import csv

# Read and verify the output file
with open('outputs/t06_stop_service_intensity.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    rows = list(reader)

print(f'Total rows: {len(rows)}')
print(f'Header: {rows[0]}')
print(f'Number of columns in header: {len(rows[0])}')

# Check that all data rows have 8 columns
errors = []
for i, row in enumerate(rows[1:], 1):
    if len(row) != 8:
        errors.append(f'Row {i} has {len(row)} columns instead of 8')

if errors:
    for e in errors:
        print(f'ERROR: {e}')
else:
    print('All rows have correct number of columns (8)')

# Check a specific stop that has comma in name
for row in rows[1:]:
    if 'Av. Elche, 174' in row[1]:
        print(f\"Row with 'Av. Elche, 174': {row}\")
        break
